import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function readExplorerFile(t){return readFileSync(resolve(__dirname,"../../calcutta-1946-crisis-explorer",t),"utf-8")}function readLandingPage(){return readFileSync(resolve(__dirname,"../../../index.html"),"utf-8")}function readSearchIndex(){return readFileSync(resolve(__dirname,"../../search-index.js"),"utf-8")}describe("1946 Calcutta Crisis Explorer — Page Structure",()=>{let t;beforeAll(()=>{t=readExplorerFile("index.html")}),it("contains a hero section with page title and kicker",()=>{expect(t).toContain('class="cc-hero"'),expect(t).toContain("<h1>"),expect(t).toContain("1946 Calcutta Crisis"),expect(t).toContain("Great Calcutta Killings"),expect(t).toContain("Road to Partition")}),it("contains all required content sections from the issue",()=>{["overview","calcutta","direct-action","events","map","spread","impact","response","reactions","bengal","timeline","references"].forEach(e=>{expect(t).toContain(`id="${e}"`),expect(t).toContain(`data-tab="${e}"`)})}),it("contains all required historical topics",()=>{["Political Background","Direct Action Day","Calcutta Context","Events of August 1946","Spread of Violence","Human Impact","Administrative Response","Political Reactions","Wider Bengal","Historical","Timeline","References"].forEach(e=>{expect(t).toContain(e)})}),it("contains key historical details and figures",()=>{expect(t).toContain("16 Aug 1946"),expect(t).toContain("Muhammad Ali Jinnah"),expect(t).toContain("Cabinet Mission"),expect(t).toContain("Suhrawardy"),expect(t).toContain("Lahore Resolution"),expect(t).toContain("Noakhali"),expect(t).toContain("Bihar"),expect(t).toContain("Gandhi")}),it("presents sensitive material respectfully",()=>{expect(t).toContain("A note on sensitivity"),expect(t).toContain("solemn"),expect(t).toContain("respectfully"),expect(t).toContain("honouring the human cost")}),it("has a semantic heading hierarchy (single h1, multiple h2s)",()=>{const e=(t.match(/<h1[\s>]/g)||[]).length,i=(t.match(/<h2[\s>]/g)||[]).length;expect(e).toBe(1),expect(i).toBeGreaterThanOrEqual(10)}),it("includes interactive features: map, timeline, spread visualization, and political context",()=>{expect(t).toContain('id="cc-calcutta-map"'),expect(t).toContain('id="cc-interactive-timeline"'),expect(t).toContain("cc-spread-chain"),expect(t).toContain("Political Background"),expect(t).toContain("cc-map-detail")}),it("links the shared stylesheet, page stylesheet, Leaflet, and script",()=>{expect(t).toContain('href="../../styles.css"'),expect(t).toContain('href="style.css"'),expect(t).toContain('src="script.js"'),expect(t).toContain("leaflet")}),it("references reliable historical sources",()=>{expect(t).toContain("britannica.com"),expect(t).toContain("wikipedia.org"),expect(t).toContain("Chatterji"),expect(t).toContain("Wolpert"),expect(t).toContain("Yasmin Khan")})}),describe("1946 Calcutta Crisis Explorer — Assets",()=>{it("includes a non-empty stylesheet themed for the subject",()=>{const t=readExplorerFile("style.css");expect(t.length).toBeGreaterThan(1e3),expect(t).toContain(".cc-hero"),expect(t).toContain(".cc-map"),expect(t).toContain(".cc-timeline"),expect(t).toContain(".cc-spread-chain")}),it("includes a valid interactive script with required functions",()=>{const t=readExplorerFile("script.js");expect(t).toContain("activateTab"),expect(t).toContain("initCalcuttaMap"),expect(t).toContain("CC_MAP_POINTS"),expect(t).toContain("initTimeline"),expect(t).toContain("initThemeToggle"),expect(t).toContain("registerSearchItems"),expect(t).toContain("Journey"),expect(t).toContain("document.addEventListener('DOMContentLoaded'")})}),describe("1946 Calcutta Crisis — Landing Page Integration",()=>{it('is listed under "Road to Partition" in the landing page navigation',()=>{const t=readLandingPage(),e=t.indexOf("Road to Partition ▾");expect(e).toBeGreaterThan(-1);const i=t.slice(e,e+900);expect(i).toContain("calcutta-1946-crisis-explorer/index.html"),expect(i).toContain("1946 Calcutta Crisis")}),it("is added to the global search index under Road to Partition",()=>{const t=readSearchIndex();expect(t).toContain("1946 Calcutta Crisis Explorer"),expect(t).toContain("Road to Partition"),expect(t).toContain("frontend/calcutta-1946-crisis-explorer/index.html")})});